export function cleanCollections(value){const input=value && typeof value==='object'?value:{};return {schema:1,groups:Array.isArray(input.groups)?input.groups.filter(g=>g && typeof g.id==='string' && typeof g.name==='string').slice(0,20).map(g=>({...g,name:g.name.slice(0,70),ids:[...new Set((Array.isArray(g.ids)?g.ids:[]).filter(x=>typeof x==='string'))].slice(0,100)})):[],notes:input.notes && typeof input.notes==='object' && !Array.isArray(input.notes)?Object.fromEntries(Object.entries(input.notes).filter(([id,note])=>typeof note==='string').map(([id,note])=>[id,note.slice(0,2000)])):{} };}
export function setMembership(value,groupId,courseId){const state=cleanCollections(value);return {...state,groups:state.groups.map(g=>g.id===groupId?{...g,ids:g.ids.includes(courseId)?g.ids.filter(id=>id!==courseId):[...g.ids,courseId]}:g)};}
export function removeCollection(value,id){const state=cleanCollections(value);return {...state,groups:state.groups.filter(g=>g.id!==id)};}
export function comparisonState(courses,value){const values=courses.map(value);const missing=values.filter(v=>v==='Not recorded').length;return {missing,different:missing===0 && new Set(values).size>1};}
export function ratingComparable(course){return Number.isFinite(Number(course.rating_mean)) && course.rating_mean!=null && Number(course.rating_scale)>0?String(Number(course.rating_mean)/Number(course.rating_scale)):'Not recorded';}
export function sourceLocation(record){const url=record.url || '';try{const parsed=new URL(url,'http://curricupath.local');if(!['https:','http:'].includes(parsed.protocol))return null;if(record.status!=='verified' && record.verification_status!=='verified')return null;const page=String(record.page || record.handbook_page || '');if(/\.pdf$/i.test(parsed.pathname) && /^\d+$/.test(page))parsed.hash=`page=${Number(page)+Number(record.pageOffset || 0)}`;return parsed.origin==='http://curricupath.local'?parsed.pathname+parsed.hash:parsed.href;}catch{return null;}}
export function resolveSourceReference(current,packaged={}){
 const version=current.version || current.academic_year || current.edition_year;
 const status=current.status || current.verification_status;
 const compatible=(!version || String(version)===String(packaged.version)) && (!current.title || current.title===packaged.title) && (!status || status==='verified');
 return {...packaged,...current,id:current.id || current.source_id || packaged.id,status:status || packaged.status,version:version || packaged.version,pageOffset:current.pageOffset ?? current.handbook_page_offset ?? (compatible?packaged.pageOffset:0),sha256:current.sha256 || (compatible?packaged.sha256:null),url:current.url || (compatible?packaged.url:null)};
}
export function escapeHtml(value){return String(value ?? '').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');}
export function offlineReading(title,text){return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(title)}</title><style>body{max-width:70ch;margin:48px auto;padding:24px;background:#f5f2eb;color:#162438;font:16px/1.8 system-ui}pre{white-space:pre-wrap;overflow-wrap:anywhere}aside{padding:18px;border:2px solid #91641d}h1{font:40px Georgia}</style><h1>${escapeHtml(title)}</h1><aside>Offline reading copy captured ${new Date().toISOString()}. It cannot verify current requirements, enrolment or eligibility. Catalogue version is supplied only where present in the references. Replace this file by exporting a fresh copy after checking online. No scripts, network requests or live evaluation are included.</aside><pre>${escapeHtml(text)}</pre></html>`;}
export function calendarEvent({title,date,time,duration=60}){if(!/^\d{4}-\d{2}-\d{2}$/.test(date) || !/^\d{2}:\d{2}$/.test(time) || !title.trim())throw new Error('Choose a title, valid date and start time.');if(!Number.isFinite(Number(duration)) || Number(duration)<=0 || Number(duration)>1440)throw new Error('Choose a duration between 1 and 1440 minutes.');const start=new Date(`${date}T${time}:00+02:00`);if(!Number.isFinite(start.getTime()) || new Date(`${date}T12:00:00Z`).toISOString().slice(0,10)!==date || Number(time.slice(0,2))>23 || Number(time.slice(3))>59)throw new Error('Check the date and time.');const utc=d=>d.toISOString().replaceAll('-','').replaceAll(':','').replace(/\.\d{3}/,'');const escaped=value=>String(value).replaceAll('\r','').replaceAll('\\','\\\\').replaceAll('\n','\\n').replaceAll(',','\\,').replaceAll(';','\\;');return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//CurricuPath//Personal Study Intention//EN','BEGIN:VEVENT',`UID:${crypto.randomUUID()}@curricupath.local`,`DTSTAMP:${utc(new Date())}`,`DTSTART:${utc(start)}`,`DTEND:${utc(new Date(start.getTime()+Number(duration)*60000))}`,`SUMMARY:${escaped(title.slice(0,120))}`,'DESCRIPTION:Personal study intention. Not an official university date or verified module offering.','END:VEVENT','END:VCALENDAR',''].map(foldCalendarLine).join('\r\n');}

function foldCalendarLine(line){let result='',segment='',bytes=0;for(const char of line){const size=new TextEncoder().encode(char).length;if(bytes+size>75){result+=segment+'\r\n';segment=' ';bytes=1;}segment+=char;bytes+=size;}return result+segment;}
